-- 按先进先出假设推算库存库龄
-- 原生MySQL 8.4未执行。先从第二部分资源导入对应隔离数据库。
-- 公开基准参考解；独立执行等价解，不得变动原库。
WITH a AS (SELECT warehouse_id,product_id,'2023-01-01' d,0 seq,quantity q FROM inventory_opening WHERE quantity>0 UNION ALL SELECT warehouse_id,product_id,movement_date,movement_id,quantity_delta FROM stock_movements WHERE quantity_delta>0), b AS (SELECT *,SUM(q) OVER(PARTITION BY warehouse_id,product_id ORDER BY d,seq ROWS UNBOUNDED PRECEDING) cum FROM a), s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' GROUP BY warehouse_id,product_id), z AS (SELECT b.*,CASE WHEN b.cum<=COALESCE(s.sold,0) THEN 0 WHEN b.cum-b.q>=COALESCE(s.sold,0) THEN b.q ELSE b.cum-COALESCE(s.sold,0) END remain FROM b LEFT JOIN s ON s.warehouse_id=b.warehouse_id AND s.product_id=b.product_id), g AS (SELECT warehouse_id,product_id,SUM(CASE WHEN d<='2025-07-04' THEN remain ELSE 0 END) aged,SUM(remain) total FROM z GROUP BY warehouse_id,product_id) SELECT g.warehouse_id,g.product_id,g.aged aged_units,g.aged*i.unit_cost_cents aged_value_cents,ROUND(100.0*g.aged/NULLIF(g.total,0),2) aged_pct FROM g JOIN inventory_snapshots i ON i.warehouse_id=g.warehouse_id AND i.product_id=g.product_id AND i.snapshot_date='2025-12-31' WHERE g.aged>0 ORDER BY aged_value_cents DESC,g.warehouse_id,g.product_id;

-- 等价解（SQLite已验证，MySQL待复验）
WITH a AS (SELECT warehouse_id,product_id,'2023-01-01' d,0 seq,quantity q FROM inventory_opening WHERE NOT (quantity<=0) UNION ALL SELECT warehouse_id,product_id,movement_date,movement_id,quantity_delta FROM stock_movements WHERE quantity_delta>0), b AS (SELECT *,SUM(q) OVER(PARTITION BY warehouse_id,product_id ORDER BY d,seq ROWS UNBOUNDED PRECEDING) cum FROM a), s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' GROUP BY warehouse_id,product_id), z AS (SELECT b.*,CASE WHEN b.cum<=COALESCE(s.sold,0) THEN 0 WHEN b.cum-b.q>=COALESCE(s.sold,0) THEN b.q ELSE b.cum-COALESCE(s.sold,0) END remain FROM b LEFT JOIN s ON s.warehouse_id=b.warehouse_id AND s.product_id=b.product_id), g AS (SELECT warehouse_id,product_id,SUM(CASE WHEN d<='2025-07-04' THEN remain ELSE 0 END) aged,SUM(remain) total FROM z GROUP BY warehouse_id,product_id) SELECT g.warehouse_id,g.product_id,g.aged aged_units,g.aged*i.unit_cost_cents aged_value_cents,ROUND(100.0*g.aged/NULLIF(g.total,0),2) aged_pct FROM g JOIN inventory_snapshots i ON i.warehouse_id=g.warehouse_id AND i.product_id=g.product_id AND i.snapshot_date='2025-12-31' WHERE g.aged>0 ORDER BY aged_value_cents DESC,g.warehouse_id,g.product_id;
